def validate_destination(root: Path, filename: str) -> Path:
    root = root.resolve()
    candidate = Path(filename)
    destination = (
        candidate if candidate.is_absolute() else root / candidate
    ).resolve()
    if not destination.is_relative_to(root):
        raise PermissionError(f"Save screenshots under {root}")
    return destination

