async def save_screenshot(original_tool, root: Path, filename: str):
    try:
        destination = validate_destination(root, filename)
    except PermissionError as error:
        return f"Access denied: {error}. Provide a valid filename."
    return await original_tool.ainvoke({"filename": str(destination)})
